import { BUILTIN_GESTURES } from "./builtinMotions.generated";

/**
 * Gesture registry: built-in clips merged with a deployment's own.
 *
 * Built-in gestures are original clips generated by
 * scripts/generate-motions.mjs (see that file and public/gestures/README.md).
 * They target the VRM normalized humanoid, so they work on every avatar in
 * Seiza — uploaded VRMs, deployer presets, and designed avatars — with no
 * per-avatar rigging.
 *
 * A deployment adds its own `.vrma` clips through `customGestures` in
 * world.json:
 *   - a custom gesture whose `name` matches a built-in REPLACES it (same
 *     slot in the list, marked as custom in the UI);
 *   - any other name is ADDED alongside the built-ins.
 * Every client reads the same world.json, so a custom gesture resolves to
 * the same clip for everyone in the room.
 */

export interface CustomGestureConfig {
  name: string;
  label: string;
  /** Same-origin path (e.g. /gestures/custom/bow.vrma) or https URL. */
  url: string;
  /** True if the clip drives the legs too (sitting, kneeling, dancing).
   *  Upper-body clips layer over walking; full-body clips replace it. */
  fullBody?: boolean;
  /** True if the clip should stop on its final pose and stay there until
   *  released, instead of playing once. Use it for a raised hand or any
   *  other posture a player holds. */
  hold?: boolean;
}

export interface GestureDefinition {
  name: string;
  label: string;
  url: string;
  fullBody: boolean;
  /** Holds its final pose until released (see CustomGestureConfig.hold). */
  hold: boolean;
  /** Not offered in the menu or on the number keys — something else in the
   *  app triggers it. `sit` is the built-in example: chairs trigger it. */
  hidden: boolean;
  /** Known up front for built-ins; custom clips report theirs on load. */
  duration: number | null;
  source: "builtin" | "custom";
  /** True when this custom clip replaced a built-in of the same name. */
  overridesBuiltin: boolean;
}

const NAME = /^[a-z0-9][a-z0-9_-]{0,31}$/;
const isAllowedUrl = (url: string) => (url.startsWith("/") && !url.startsWith("//")) || /^https:\/\//i.test(url);

export function buildGestureRegistry(options: {
  enabledGestures?: string[];
  customGestures?: CustomGestureConfig[];
}): GestureDefinition[] {
  const enabled = options.enabledGestures?.length ? new Set(options.enabledGestures) : null;

  const list: GestureDefinition[] = BUILTIN_GESTURES.filter((g) => !enabled || enabled.has(g.name)).map((g) => ({
    name: g.name,
    label: g.label,
    url: g.url,
    fullBody: g.fullBody,
    hold: g.hold,
    hidden: g.hidden,
    duration: g.duration,
    source: "builtin",
    overridesBuiltin: false,
  }));

  for (const custom of options.customGestures ?? []) {
    if (!custom || typeof custom.name !== "string" || !NAME.test(custom.name)) {
      console.warn("Ignoring custom gesture with an invalid name (use lowercase letters, digits, - or _):", custom);
      continue;
    }
    if (typeof custom.url !== "string" || !isAllowedUrl(custom.url)) {
      console.warn(`Ignoring custom gesture "${custom.name}": url must be a same-origin path or https URL.`);
      continue;
    }
    const definition: GestureDefinition = {
      name: custom.name,
      label: typeof custom.label === "string" && custom.label.trim() ? custom.label.trim().slice(0, 40) : custom.name,
      url: custom.url,
      fullBody: custom.fullBody === true,
      hold: custom.hold === true,
      // A custom clip replacing a hidden built-in (`sit`) stays hidden, so
      // a deployment can supply its own sitting pose without it showing up
      // in the menu as a gesture.
      hidden: BUILTIN_GESTURES.some((g) => g.name === custom.name && g.hidden),
      duration: null,
      source: "custom",
      overridesBuiltin: false,
    };
    const existing = list.findIndex((g) => g.name === custom.name);
    if (existing >= 0) {
      list[existing] = { ...definition, overridesBuiltin: list[existing].source === "builtin" };
    } else {
      list.push(definition);
    }
  }

  return list;
}

export function isValidGestureName(name: unknown): name is string {
  return typeof name === "string" && NAME.test(name);
}

/** The clip a seated avatar holds. Named `sit` so a deployment can replace
 *  it through `customGestures` like any other gesture. */
export const SIT_GESTURE_NAME = "sit";

export function findGesture(gestures: GestureDefinition[], name: string | null): GestureDefinition | null {
  if (!name) return null;
  return gestures.find((g) => g.name === name) ?? null;
}

